// MovieDuels 2026-11-22: every humanoid set's own animation versions, merged into the Master
// _humanoid (models/players/_humanoid/animation.cfg). NAME_SET = that set's pose or timing for NAME,
// e.g. BOTH_RUN2_ANI comes from _humanoid_ani (_GRIEV = _humanoid_grievous). Generated list.
// X-macro: define ANIM_VARIANT(x) before including (anims.h: enum entry, animtable.h: ENUM2STRING).
// No include guard on purpose. MP's automatic style swap (BG_BuildStyleAnims) skips these.
// 2026-11-23: the MD cutscene anims BOTH_CIN_1 .. BOTH_CIN_104 and BOTH_MD_CIN_n exist ONCE (the MD team's Master,
// 'mdcutscenes'): no BOTH_CIN_n_<SET> / BOTH_MD_CIN_n_<SET> versions here or in animation.cfg. Every character shares
// them: the mission scripts play BOTH_CIN_n / BOTH_MD_CIN_n, whatever the character's style. (The maps' own
// BOTH_CIN_n_<MAP> below are another thing and stay.)

// were missing from Master and from the enum
